const path = require("node:path");
const {
  createContractProgram,
  renderTypeAliases,
  writeOrCheckContract,
  checkContractDeclarations,
} = require("./contract-generation.cjs");

const source = path.resolve(__dirname, "../src/api/vendor/order-notifications/contracts.ts");
const target = path.resolve(__dirname, "../.mercur/order-notification-contracts.d.ts");
const program = createContractProgram([source], { skipLibCheck: false });
const result =
  "// Generated by scripts/generate-order-notification-contracts.cjs. Do not edit.\n" +
  renderTypeAliases(program, [source]) +
  "\n";

if (
  writeOrCheckContract(
    target,
    result,
    "Order notification contracts are stale; run pnpm orders:contracts:generate",
  )
) {
  checkContractDeclarations(
    [target],
    "Order notification contract declaration failed typechecking",
  );
}
